 build:build('Total the urgent visits, not every visit on their pumps','The site report reads pump documents containing visit arrays.','Select the requested site, expand visits, keep the requested urgent kind and sum visits.minutes under site. Return sorted {key,total} records; no qualifying visits means [].',{documents:'Pumps with recent visits',site:'Requested site',kind:'Visit kind to count'},[sample('Only urgent visits at north',{documents:[{asset_id:'P1',site:'north',visits:[{kind:'urgent',minutes:12}]},{asset_id:'P2',site:'north',visits:[{kind:'urgent',minutes:8}]}],site:'north',kind:'urgent'},[{key:'north',total:20}]),sample('Routine work appears on the same pump',{documents:[{asset_id:'P1',site:'north',visits:[{kind:'urgent',minutes:12},{kind:'routine',minutes:30}]},{asset_id:'P2',site:'north',visits:[{kind:'urgent',minutes:8}]},{asset_id:'P3',site:'south',visits:[{kind:'urgent',minutes:99}]}],site:'north',kind:'urgent'},[{key:'north',total:20}])],configured('nsGroupSum',{key:'site',amount:'visits.minutes'},filter('visits.kind','=',configured('nsUnwind',{field:'visits'},filter('site','=',s('documents'),s('site'))),s('kind'))),'Each surviving visit contributes once; parent selection alone cannot exclude routine members.',['Keep site filtering before expansion.','Filter visit kind after expansion and before the sum.']),
